import React from "react";
import { TEMPLATES } from "../data/templates.js";

/**
 * Smart Layout Template Picker
 * Props:
 *   - templateId, setTemplateId, openExternal  (existing)
 *   - role?: string                            (optional; e.g., "Frontend Engineer")
 *   - resume?: object                          (optional; to derive suggestions)
 *
 * This adds a "Suggestions for you" panel with 1-click picks like:
 *   - Experience-first
 *   - Projects-first
 *   - Skills-first (JD-heavy)
 *   - Compact 1-page
 */
export default function LayoutTemplatePicker({
  templateId,
  setTemplateId,
  openExternal,
  role,        // optional
  resume       // optional
}) {
  // Safeguards
  const templates = Array.isArray(TEMPLATES) ? TEMPLATES : [];
  const fallbackId = templates[0]?.id || templateId;

  const stats = React.useMemo(() => {
    const r = resume || {};
    const exps = Array.isArray(r.experience) ? r.experience : [];
    const projs = Array.isArray(r.projects) ? r.projects : [];
    const bulletsIn = (arr) =>
      arr.reduce((sum, it) => sum + (Array.isArray(it?.bullets) ? it.bullets.filter(Boolean).length : 0), 0);

    const totalBullets = bulletsIn(exps) + bulletsIn(projs);
    const metricy = hasMetrics(exps) || hasMetrics(projs);
    return {
      expCount: exps.length,
      projCount: projs.length,
      totalBullets,
      metricy
    };
  }, [resume]);

  const suggestions = React.useMemo(() => {
    // Helper to find a template id by preferred names (name or id contains token)
    const pick = (names) => {
      const lower = (s) => String(s || "").toLowerCase();
      for (const token of names) {
        const found = templates.find(
          (t) => lower(t.name).includes(token) || lower(t.id).includes(token)
        );
        if (found) return found.id;
      }
      return fallbackId;
    };

    // Heuristics
    const r = role ? String(role).toLowerCase() : "";
    const toolHeavy =
      /devops|cloud|data|machine learning|ml|backend|platform|sre|infra/.test(r);

    const projectsFirstId = pick(["project", "portfolio"]);
    const experienceFirstId = pick(["experience", "classic", "chronological"]);
    const skillsFirstId = pick(["skills", "functional"]);
    const compactId = pick(["compact", "condensed", "modern"]);

    const items = [];

    // Primary suggestion by profile shape
    if (stats.projCount > stats.expCount || stats.expCount <= 1) {
      items.push({
        id: projectsFirstId,
        label: "Projects-first",
        reason: "You have stronger/greater number of projects than roles — show them first."
      });
    } else {
      items.push({
        id: experienceFirstId,
        label: "Experience-first",
        reason: stats.metricy
          ? "Your bullets already show impact (latency %, cost, p95). Lead with Experience."
          : "Multiple roles to showcase — a chronological, Experience-first layout reads best."
      });
    }

    // Secondary: skills-first for tool-heavy or JD-strict roles
    items.push({
      id: skillsFirstId,
      label: "Skills-first (JD-heavy)",
      reason: toolHeavy
        ? "Roles like DevOps/Data/Cloud score keyword coverage; put Skills high."
        : "If the JD has strict tool requirements, surface Skills at the top."
    });

    // Tertiary: compact if content is dense
    if (stats.totalBullets >= 16) {
      items.push({
        id: compactId,
        label: "Compact 1-page",
        reason: "You have many bullets; a tighter template keeps it on one page."
      });
    }

    // Ensure uniqueness and keep 3
    const uniq = [];
    for (const it of items) {
      if (!uniq.find((x) => x.id === it.id)) uniq.push(it);
    }
    return uniq.slice(0, 3);
  }, [templates, fallbackId, role, stats]);

  const selected = templates.find((t) => t.id === templateId);

  return (
    <div className="p-4 rounded-xl bg-white/5 border border-white/10">
      <div className="font-semibold mb-2">Layout Template</div>

      <select
        className="w-full bg-slate-800 border border-white/10 rounded-lg px-2 py-2 text-sm"
        value={templateId}
        onChange={(e) => setTemplateId(e.target.value)}
        aria-label="Select resume layout template"
      >
        {templates.map((t) => (
          <option key={t.id} value={t.id}>
            {t.name}
          </option>
        ))}
      </select>

      {selected?.desc && (
        <div className="text-xs text-slate-400 mt-1">{selected.desc}</div>
      )}

      {/* Suggestions */}
      <div className="mt-3 rounded-lg border border-white/10 bg-white/5">
        <div className="px-3 py-2 text-xs text-slate-300 border-b border-white/10">
          Suggestions for you
        </div>
        <div className="p-3 grid gap-2">
          {suggestions.length === 0 ? (
            <div className="text-xs text-slate-400">
              Pick a template above — we’ll suggest options based on your role and content.
            </div>
          ) : (
            suggestions.map((s, i) => (
              <div
                key={s.id}
                className="flex items-center justify-between rounded-md bg-slate-800/70 border border-white/10 px-3 py-2"
              >
                <div className="text-sm">
                  <div className="font-medium">
                    {s.label}
                    {i === 0 ? (
                      <span className="ml-2 text-emerald-300 text-xs align-middle">Recommended</span>
                    ) : null}
                  </div>
                  <div className="text-xs text-slate-300">{s.reason}</div>
                </div>
                <button
                  className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10"
                  onClick={() => setTemplateId(s.id)}
                  type="button"
                  title={`Use ${s.label}`}
                >
                  Use this
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      <button
        className="mt-3 text-xs underline text-slate-300"
        onClick={openExternal}
        type="button"
      >
        Want more templates from the web?
      </button>
    </div>
  );
}

/* ---------- helpers ---------- */
function hasMetrics(items) {
  const arr = Array.isArray(items) ? items : [];
  const anyBulletMatches = arr.some((x) =>
    (x?.bullets || []).some((b) =>
      typeof b === "string" &&
      /\b(\d+%|\d+ ?(ms|s|m|min|h|hours)|p\d{2}|x|\$|₹|€|£|#)\b/i.test(b)
    )
  );
  return anyBulletMatches;
}
