
import React from "react";

export default function SectionEditor({ title, items = [], onAdd, onRemove, render }) {
  return (
    <div className="rounded-xl bg-white/5 border border-white/10 p-4">
      <div className="flex items-center justify-between mb-2">
        <div className="font-semibold">{title}</div>
        <button className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10" onClick={onAdd}>+ Add</button>
      </div>
      <div className="space-y-4">
        {(items||[]).map((x, idx) => (
          <div key={x.id || idx} className="rounded-lg bg-slate-800/70 border border-white/10 p-3">
            <div className="flex justify-between items-center mb-2">
              <div className="text-xs text-slate-300">#{idx + 1}</div>
              {(items||[]).length > 1 && <button className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10" onClick={() => onRemove(x.id || idx)}>Remove</button>}
            </div>
            {render(x, idx)}
          </div>
        ))}
      </div>
    </div>
  );
}
