import React from "react";
import { createPortal } from "react-dom";

export default function ExportMenu({ onTXT, onPDF, onDOCX }) {
  console.log("ExportMenu v5 (portal + capture) loaded");
  const [open, setOpen] = React.useState(false);
  const btnRef = React.useRef(null);
  const menuRef = React.useRef(null);
  const firstItemRef = React.useRef(null);
  const [pos, setPos] = React.useState({ top: 0, left: 0, width: 192 });

  const updatePosition = React.useCallback(() => {
    const btn = btnRef.current;
    if (!btn) return;
    const r = btn.getBoundingClientRect();
    const width = 192;
    const gap = 8;
    const left = Math.max(8, Math.min(window.innerWidth - width - 8, r.right - width));
    const top = Math.min(window.innerHeight - 8, r.bottom + gap);
    setPos({ top, left, width });
  }, []);

  React.useEffect(() => {
    if (!open) return;
    updatePosition();

    // capture-phase outside click wins even if parents stopPropagation
    const onPointerDownCapture = (e) => {
      const btn = btnRef.current;
      const menu = menuRef.current;
      if ((btn && btn.contains(e.target)) || (menu && menu.contains(e.target))) return;
      setOpen(false);
    };
    const onKey = (e) => { if (e.key === "Escape") setOpen(false); };
    const onViewport = () => updatePosition();

    document.addEventListener("pointerdown", onPointerDownCapture, true);
    window.addEventListener("keydown", onKey);
    window.addEventListener("resize", onViewport);
    window.addEventListener("scroll", onViewport, true);

    return () => {
      document.removeEventListener("pointerdown", onPointerDownCapture, true);
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("resize", onViewport);
      window.removeEventListener("scroll", onViewport, true);
    };
  }, [open, updatePosition]);

  React.useEffect(() => {
    if (open && firstItemRef.current) firstItemRef.current.focus();
  }, [open]);

  return (
    <div className="relative inline-block">
      <button
        ref={btnRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className="px-3 py-2 rounded-lg bg-white/10 hover:bg-white/15 border border-white/15 text-sm"
      >
        Export ▼
      </button>

      {open &&
        createPortal(
          <div className="fixed inset-0" style={{ zIndex: 2147483646 }}>
            {/* transparent backdrop; clicks handled by document capture listener */}
            <div className="absolute inset-0" />
            <div
              ref={menuRef}
              role="menu"
              aria-label="Export options"
              className="absolute rounded-lg bg-slate-800 border border-white/10 shadow-lg py-1"
              style={{ top: pos.top, left: pos.left, width: pos.width, zIndex: 2147483647 }}
            >
              <button
                ref={firstItemRef}
                role="menuitem"
                onClick={() => { setOpen(false); onTXT(); }}
                className="w-full text-left px-3 py-2 hover:bg-white/10 text-sm focus:outline-none"
              >
                Download TXT
              </button>
              <button
                role="menuitem"
                onClick={() => { setOpen(false); onPDF(); }}
                className="w-full text-left px-3 py-2 hover:bg-white/10 text-sm focus:outline-none"
              >
                Download PDF
              </button>
              <button
                role="menuitem"
                onClick={() => { setOpen(false); onDOCX(); }}
                className="w-full text-left px-3 py-2 hover:bg-white/10 text-sm focus:outline-none"
              >
                Download DOCX
              </button>
            </div>
          </div>,
          document.body
        )}
    </div>
  );
}
