
import React from "react";

export default function BulletsEditor({ bullets = [""], onChange }) {
  const update = (i, v) => { const next = bullets.slice(); next[i] = v; onChange(next); };
  const add = () => onChange([...(bullets||[]), ""]);
  const remove = (i) => onChange((bullets||[]).filter((_, j) => j !== i));

  return (
    <div>
      <div className="font-medium text-sm mb-1">Bullets</div>
      <div className="space-y-2">
        {(bullets||[]).map((b, i) => (
          <div key={i} className="flex gap-2">
            <input className="flex-1 bg-slate-800 border border-white/10 rounded-lg px-3 py-2" placeholder="Improved X by Y% by doing Z…" value={b} onChange={(e) => update(i, e.target.value)} />
            {(bullets||[]).length > 1 && <button className="px-2 rounded-lg bg-white/10 border border-white/10 text-xs" onClick={() => remove(i)}>✕</button>}
          </div>
        ))}
      </div>
      <div className="mt-2 flex items-center gap-2">
        <button className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10" onClick={add}>+ Add bullet</button>
        <span className="text-xs text-slate-400">Prefer 12–22 words, start with a verb, add a number.</span>
      </div>
    </div>
  );
}
