import React from "react";

/**
 * Education.jsx (grouped version)
 *
 * Data model (unchanged array, but adds "etype" for grouping):
 *   resume.education: [{
 *     id: string,
 *     etype: "school" | "ug" | "pg" | "other" | "cert",
 *     school: string,   // institution | certification name
 *     degree: string,   // degree/program | issuer | board/stream
 *     year: string
 *   }]
 *
 * Props expected (same as before; we only need updateField + resume):
 *   - resume, updateField
 *   - addItem/removeItem are no longer needed here (we manage adds/removes),
 *     but keeping them in the signature is harmless.
 */

export default function Education({ resume, updateField /*, addItem, removeItem */ }) {
  const edu = Array.isArray(resume.education) ? resume.education : [];

  const uid = () => Math.random().toString(36).slice(2);

  const setEdu = (next) => updateField("education", next);

  const addRow = (etype) => {
    const template = {
      id: uid(),
      etype,
      school: "",
      degree: "",
      year: ""
    };
    setEdu([...edu, template]);
  };

  const removeRow = (id) => {
    setEdu(edu.filter((e) => e.id !== id));
  };

  const updateRow = (id, patch) => {
    setEdu(
      edu.map((e) => (e.id === id ? { ...e, ...patch } : e))
    );
  };

  const listBy = (etype) => edu.filter((e) => e.etype === etype);

  return (
    <div className="rounded-xl bg-white/5 border border-white/10 p-4">
      <div className="font-semibold mb-3">Education</div>

      {/* School */}
      <Group
        title="School"
        hint="e.g., High School (Class X/XII) — Board/Stream"
        rows={listBy("school")}
        onAdd={() => addRow("school")}
        render={(row) => (
          <RowTwoUp
            leftPlaceholder="School (e.g., ABC Senior Secondary)"
            rightPlaceholder="Year"
            leftValue={row.school}
            rightValue={row.year}
            onLeft={(v) => updateRow(row.id, { school: v })}
            onRight={(v) => updateRow(row.id, { year: v })}
            underPlaceholder="Board / Stream (optional)"
            underValue={row.degree}
            onUnder={(v) => updateRow(row.id, { degree: v })}
            onRemove={() => removeRow(row.id)}
          />
        )}
      />

      {/* UG / Graduation */}
      <Group
        title="UG / Graduation"
        hint="Bachelor’s degree or equivalent"
        rows={listBy("ug")}
        onAdd={() => addRow("ug")}
        render={(row) => (
          <RowTwoUp
            leftPlaceholder="Degree / Program (e.g., B.Tech CSE)"
            rightPlaceholder="Year"
            leftValue={row.degree}
            rightValue={row.year}
            onLeft={(v) => updateRow(row.id, { degree: v })}
            onRight={(v) => updateRow(row.id, { year: v })}
            underPlaceholder="University / College"
            underValue={row.school}
            onUnder={(v) => updateRow(row.id, { school: v })}
            onRemove={() => removeRow(row.id)}
          />
        )}
      />

      {/* Post Graduation */}
      <Group
        title="Post Graduation"
        hint="Master’s / M.Tech / MBA, etc."
        rows={listBy("pg")}
        onAdd={() => addRow("pg")}
        render={(row) => (
          <RowTwoUp
            leftPlaceholder="Degree / Program (e.g., M.S. Data Science)"
            rightPlaceholder="Year"
            leftValue={row.degree}
            rightValue={row.year}
            onLeft={(v) => updateRow(row.id, { degree: v })}
            onRight={(v) => updateRow(row.id, { year: v })}
            underPlaceholder="University / College"
            underValue={row.school}
            onUnder={(v) => updateRow(row.id, { school: v })}
            onRemove={() => removeRow(row.id)}
          />
        )}
      />

      {/* Other Qualification */}
      <Group
        title="Other Qualification"
        hint="Diploma / Nanodegree / Bootcamp"
        rows={listBy("other")}
        onAdd={() => addRow("other")}
        render={(row) => (
          <RowTwoUp
            leftPlaceholder="Qualification (e.g., Diploma in ML)"
            rightPlaceholder="Year"
            leftValue={row.degree}
            rightValue={row.year}
            onLeft={(v) => updateRow(row.id, { degree: v })}
            onRight={(v) => updateRow(row.id, { year: v })}
            underPlaceholder="Institute / Provider"
            underValue={row.school}
            onUnder={(v) => updateRow(row.id, { school: v })}
            onRemove={() => removeRow(row.id)}
          />
        )}
      />

      {/* Certifications */}
      <Group
        title="Certifications"
        hint="Add certification name, issuer, and year"
        rows={listBy("cert")}
        onAdd={() => addRow("cert")}
        addLabel="Add Certification"
        render={(row) => (
          <RowTwoUp
            leftPlaceholder="Certification (e.g., AWS Solutions Architect)"
            rightPlaceholder="Year"
            leftValue={row.school}
            rightValue={row.year}
            onLeft={(v) => updateRow(row.id, { school: v })}
            onRight={(v) => updateRow(row.id, { year: v })}
            underPlaceholder="Issuer / Platform (e.g., AWS, Coursera)"
            underValue={row.degree}
            onUnder={(v) => updateRow(row.id, { degree: v })}
            onRemove={() => removeRow(row.id)}
          />
        )}
      />

      {/* Legacy rows (no etype) — keep them visible so nothing is lost */}
      {edu.some((e) => !e.etype) && (
        <Group
          title="(Imported / Legacy)"
          hint="These entries were imported and lack a category. You can copy/edit them or move into a category above."
          rows={edu.filter((e) => !e.etype)}
          onAdd={null}
          render={(row) => (
            <RowThree
              p1={{ placeholder: "School / Program", value: row.school, on: (v) => updateRow(row.id, { school: v }) }}
              p2={{ placeholder: "Degree / Board / Issuer", value: row.degree, on: (v) => updateRow(row.id, { degree: v }) }}
              p3={{ placeholder: "Year", value: row.year, on: (v) => updateRow(row.id, { year: v }) }}
              onRemove={() => removeRow(row.id)}
            />
          )}
        />
      )}
    </div>
  );
}

/* ---------- UI helpers ---------- */

function Group({ title, hint, rows, onAdd, addLabel = "Add", render }) {
  return (
    <div className="mb-5">
      <div className="flex items-center justify-between mb-1">
        <div className="font-medium">{title}</div>
        {onAdd && (
          <button
            type="button"
            className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10"
            onClick={onAdd}
          >
            {addLabel}
          </button>
        )}
      </div>
      {hint && <div className="text-xs text-slate-400 mb-2">{hint}</div>}
      <div className="space-y-2">
        {rows.length === 0 ? (
          <div className="text-xs text-slate-400">No entries yet.</div>
        ) : (
          rows.map((r) => <div key={r.id}>{render(r)}</div>)
        )}
      </div>
    </div>
  );
}

function RowTwoUp({
  leftPlaceholder,
  rightPlaceholder,
  underPlaceholder,
  leftValue,
  rightValue,
  underValue,
  onLeft,
  onRight,
  onUnder,
  onRemove
}) {
  return (
    <div className="rounded-lg bg-slate-800/70 border border-white/10 p-3">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
        <input
          className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2 md:col-span-2"
          placeholder={leftPlaceholder}
          value={leftValue}
          onChange={(e) => onLeft(e.target.value)}
        />
        <input
          className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
          placeholder={rightPlaceholder}
          value={rightValue}
          onChange={(e) => onRight(e.target.value)}
        />
      </div>
      <div className="mt-2 grid grid-cols-1 md:grid-cols-[1fr_auto] gap-2">
        <input
          className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
          placeholder={underPlaceholder}
          value={underValue}
          onChange={(e) => onUnder(e.target.value)}
        />
        <button
          className="px-2 rounded-lg bg-white/10 border border-white/10 text-xs h-9"
          onClick={onRemove}
          type="button"
        >
          Remove
        </button>
      </div>
    </div>
  );
}

function RowThree({ p1, p2, p3, onRemove }) {
  return (
    <div className="rounded-lg bg-slate-800/70 border border-white/10 p-3">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
        <input className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2" placeholder={p1.placeholder} value={p1.value} onChange={(e) => p1.on(e.target.value)} />
        <input className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2" placeholder={p2.placeholder} value={p2.value} onChange={(e) => p2.on(e.target.value)} />
        <input className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2" placeholder={p3.placeholder} value={p3.value} onChange={(e) => p3.on(e.target.value)} />
      </div>
      <div className="mt-2 text-right">
        <button className="px-2 rounded-lg bg-white/10 border border-white/10 text-xs h-9" onClick={onRemove} type="button">
          Remove
        </button>
      </div>
    </div>
  );
}
