import { importPDF }  from "./pdfImport";
import { importDOCX } from "./docxImport";
import { importTXT }  from "./txtImport";
import { detectSections, makeReport, stripHeadersFooters } from "./common";

// High-level orchestrator: returns { meta, report, resume }
export async function importResume(file, options = {}) {
  const name = (file?.name || "").toLowerCase();
  const ext = name.split(".").pop();

  let result;
  if (ext === "pdf")      result = await importPDF(file);
  else if (ext === "docx")result = await importDOCX(file);
  else if (ext === "txt") result = await importTXT(file);
  else throw new Error("Unsupported file type. Please upload PDF, DOCX, or TXT.");

  // Optional header/footer stripping (if we later mark page breaks)
  let text = result.text;
  if (options.stripHeaders) text = stripHeadersFooters(text);

  // Map to resume object
  const resume = detectSections(text);
  const report = makeReport(text, resume, result.meta || {});
  return { meta: result.meta || {}, report, resume };
}
