import React from "react";

export default function ImportReport({ result, onClose }) {
  if (!result) return null;
  const { meta, report } = result;

  return (
    <div className="mt-4 rounded-xl border border-white/10 bg-slate-800/70 p-4">
      <div className="flex items-start justify-between">
        <div>
          <div className="text-base font-semibold">Import Report</div>
          <div className="text-xs text-slate-400">
            Source: {meta.source?.toUpperCase()}{meta.pages ? ` • ${meta.pages} page(s)` : ""} {meta.isScanned ? " • scanned?" : ""}
          </div>
        </div>
        <button onClick={onClose} className="text-xs px-2 py-1 rounded bg-white/10 hover:bg-white/20">
          Dismiss
        </button>
      </div>

      <div className="mt-3 grid grid-cols-2 md:grid-cols-4 gap-2 text-sm">
        <Stat label="Words" value={report.words} />
        <Stat label="Sections" value={report.sections} />
        <Stat label="Bullets" value={report.bullets} />
        <Stat label="Dates" value={report.dates} />
      </div>

      {report.warnings?.length ? (
        <div className="mt-3">
          <div className="text-xs font-semibold text-amber-300 mb-1">Warnings</div>
          <ul className="text-sm list-disc pl-5 space-y-1">
            {report.warnings.map((w, i) => <li key={i}>{w}</li>)}
          </ul>
        </div>
      ) : null}

      {report.fixes?.length ? (
        <div className="mt-3">
          <div className="text-xs font-semibold text-slate-300 mb-1">Fixes applied</div>
          <div className="flex flex-wrap gap-2">
            {report.fixes.map((f) => (
              <span key={f.id} className={`text-xs px-2 py-1 rounded border ${f.applied ? "border-emerald-400 text-emerald-300" : "border-slate-500 text-slate-300"}`}>
                {f.label}{f.applied ? "" : " (skipped)"}
              </span>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

function Stat({ label, value }) {
  return (
    <div className="rounded-lg bg-white/5 border border-white/10 p-2 text-center">
      <div className="text-lg font-bold">{value}</div>
      <div className="text-xs text-slate-400">{label}</div>
    </div>
  );
}
